package com.example.arcana.spell;
import com.example.arcana.capability.ManaCapability; import com.example.arcana.entity.*; import com.example.arcana.network.ArcanaNetwork; import net.minecraft.server.level.ServerPlayer; import net.minecraft.world.phys.*;
public final class ArcaneBoltSpell { public static void cast(ServerPlayer p){p.getCapability(ManaCapability.TYPE).ifPresent(m->{if(m.get()<12||p.getCooldowns().isOnCooldown(ArcanaBoltEntity.ITEM)){return;}m.set(m.get()-12);p.getCooldowns().addCooldown(ArcanaBoltEntity.ITEM,12);Vec3 v=p.getLookAngle().scale(1.5);var e=new ArcanaBoltEntity(p.level(),p);e.setRange(ArcanaBoltEntity.BASE_RANGE_BLOCKS+m.boltRangeLevel()*8);e.setPos(p.getX(),p.getEyeY()-0.1,p.getZ());e.shoot(v.x,v.y,v.z,1.6f,0);p.level().addFreshEntity(e);p.level().playSound(null,p.blockPosition(),net.minecraft.sounds.SoundEvents.EVOKER_CAST_SPELL,net.minecraft.sounds.SoundSource.PLAYERS,1,1);ArcanaNetwork.sync(p);});}
 public static void blink(ServerPlayer p){p.getCapability(ManaCapability.TYPE).ifPresent(m->{if(m.get()<20||p.getCooldowns().isOnCooldown(net.minecraft.world.item.Items.ENDER_PEARL))return;Vec3 end=p.getEyePosition().add(p.getLookAngle().scale(12));var hit=p.level().clip(new net.minecraft.world.level.ClipContext(p.getEyePosition(),end,net.minecraft.world.level.ClipContext.Block.COLLIDER,net.minecraft.world.level.ClipContext.Fluid.NONE,p));Vec3 pos=hit.getType()==HitResult.Type.MISS?end.subtract(0,1,0):hit.getLocation().subtract(p.getLookAngle().scale(1));m.set(m.get()-20);p.getCooldowns().addCooldown(net.minecraft.world.item.Items.ENDER_PEARL,30);p.teleportTo(pos.x,pos.y,pos.z);p.level().playSound(null,p.blockPosition(),net.minecraft.sounds.SoundEvents.ENDERMAN_TELEPORT,net.minecraft.sounds.SoundSource.PLAYERS,1,1);ArcanaNetwork.sync(p);});}
 public static void ward(ServerPlayer p){p.getCapability(ManaCapability.TYPE).ifPresent(m->{if(m.get()<18||p.getCooldowns().isOnCooldown(net.minecraft.world.item.Items.SHIELD))return;m.set(m.get()-18);p.getCooldowns().addCooldown(net.minecraft.world.item.Items.SHIELD,200);p.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.DAMAGE_RESISTANCE,160,1));p.level().playSound(null,p.blockPosition(),net.minecraft.sounds.SoundEvents.BEACON_ACTIVATE,net.minecraft.sounds.SoundSource.PLAYERS,1,1);ArcanaNetwork.sync(p);});}}
